b-outage.text:
[
  {
    "title": "Application Layer Exhaustion via Search",
    "description": "An attacker floods the storefront's product search API with complex, resource-intensive queries to exhaust server CPU and memory, causing the site to become unresponsive."
  },
  {
    "title": "Checkout Session Hijacking and Lockout",
    "description": "An attacker uses stolen session tokens to open thousands of checkout sessions without completing payment, exhausting the database connection pool and preventing legitimate customers from checking out."
  },
  {
    "title": "Database Query Manipulation",
    "description": "An attacker submits crafted SQL injection payloads in product filter parameters to trigger complex, time-consuming database operations that lock tables and degrade overall site performance."
  },
  {
    "title": "Image Processing Resource Starvation",
    "description": "An attacker uploads numerous malformed or large image files to the product catalog via admin endpoints, causing the image processing service to hang and consume all available worker threads."
  },
  {
    "title": "Inventory Cache Poisoning",
    "description": "An attacker sends a high volume of requests for out-of-stock items to force frequent cache misses and database hits, overwhelming the backend database and slowing down page loads for all users."
  }
]

b-payment.text:
[
  {
    "title": "Session hijacking via unencrypted checkout",
    "description": "An attacker intercepts the session cookie of a customer during the checkout process on an unencrypted connection. They then use this stolen session to access the user's account and view stored payment details."
  },
  {
    "title": "Insider theft of customer support logs",
    "description": "A malicious support agent accesses internal logs containing unmasked card tokens or sensitive customer data shared during troubleshooting. The agent exports this data to an external drive for sale on dark web markets."
  },
  {
    "title": "Cross-site scripting on product reviews",
    "description": "An attacker injects malicious JavaScript into a product review field that executes when an admin views the review. The script exfiltrates the admin's session cookie, allowing the attacker to access the admin console and view customer payment data."
  },
  {
    "title": "Backup file exposure via misconfigured storage",
    "description": "An attacker discovers a publicly accessible directory containing uncompressed database backups. These backups include plaintext or weakly encrypted copies of the customer database containing payment tokens and personal information."
  },
  {
    "title": "API endpoint enumeration for data leakage",
    "description": "An attacker identifies an undocumented API endpoint used for internal order status checks. By manipulating parameters, they retrieve full order details including customer names, addresses, and associated payment tokens for multiple users."
  }
]
